package com.kitchenos.connect.ui;
import com.kitchenos.connect.control.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class HomeVesselSignalTest {
    @Test public void pendingCheckNeverRequiresCoolingOrClaimsAbsence(){for(int heat:new int[]{0,39,40,42,60,80,100,150,180,255}){ControlState s=live();s.temperature=heat;s.potCheck.require();assertEquals(HomeVesselSignal.Kind.ACTION,HomeVesselSignal.from(s,1100).kind);assertTrue(HomeVesselSignal.from(s,1100).description().contains("Deckel öffnen"));assertFalse(s.potMissing());assertFalse(s.safe(1100,true));s.coverOpen=1;assertEquals("Topfprüfung ausstehend",s.potCheckWaitReason());}}
    private ControlState live(){ControlState s=new ControlState();s.foreground=s.connected=s.rootVerified=s.coverVerified=true;s.samples=5;s.statusAt=s.infoAt=1000;s.state=0;s.coverOpen=0;s.error=0;return s;}
    @Test public void staleReadingsCannotShowACompletedOrRunningCheck(){ControlState s=live();s.state=9;assertEquals(HomeVesselSignal.Kind.CHECKING,HomeVesselSignal.from(s,1100).kind);assertEquals(HomeVesselSignal.Kind.CONNECTION,HomeVesselSignal.from(s,1500).kind);}
    @Test public void unconfirmedStopOutranksFaultAndChecking(){ControlState s=live();s.uncertainRun=true;s.deviceFaultLatched=true;s.lastDeviceError=2;s.potCheck.begin(1);assertEquals(HomeVesselSignal.Kind.STOP_UNCONFIRMED,HomeVesselSignal.from(s,1100).kind);}
    @Test public void actualLatchedFaultPersistsThroughStopAndStaleTelemetry(){ControlState s=live();s.deviceFaultLatched=true;s.lastDeviceError=2;assertEquals(HomeVesselSignal.Kind.POT,HomeVesselSignal.from(s,5000).kind);s.lastDeviceError=14;assertEquals(HomeVesselSignal.Kind.LID,HomeVesselSignal.from(s,5000).kind);}
    @Test public void unknownCodeNeverInventsAMotorOrTemperatureCause(){ControlState s=live();s.error=193;assertEquals(HomeVesselSignal.Kind.GENERAL,HomeVesselSignal.from(s,1100).kind);assertTrue(HomeVesselSignal.from(s,1100).description().contains("193"));}
    @Test public void retainedOemCodesMapToTheirAffectedComponent(){ControlState s=live();int[] codes={1,2,5,19,29,254};HomeVesselSignal.Kind[] kinds={HomeVesselSignal.Kind.LID,HomeVesselSignal.Kind.POT,HomeVesselSignal.Kind.THERMAL,HomeVesselSignal.Kind.MOTOR,HomeVesselSignal.Kind.SCALE,HomeVesselSignal.Kind.CONNECTION};for(int i=0;i<codes.length;i++){s.error=codes[i];assertEquals(kinds[i],HomeVesselSignal.from(s,1100).kind);}}
    @Test public void diagnosticReceiptDoesNotCreateAPositiveSensorBit(){ControlState s=live();assertTrue(s.potCheck.begin(1));assertFalse(s.safe(1100));assertTrue(s.potCheck.complete(1,"clear_window",true));assertFalse(s.potVerified);assertEquals(-1,s.pot);assertEquals(HomeVesselSignal.Kind.NONE,HomeVesselSignal.from(s,1100).kind);}
    @Test public void confirmedMissingReceiptSurvivesClearedMcuError(){ControlState s=live();s.potCheck.begin(1);s.potCheck.complete(1,"missing",true);assertTrue(s.potMissing());assertFalse(s.safe(1100));assertEquals(HomeVesselState.Lid.POT_MISSING,HomeVesselState.from(s,1100).lid);}
    @Test public void receiptsRequireTheirCheckAndConfirmedStop(){PotCheckState check=new PotCheckState();assertTrue(check.begin(4));assertFalse(check.begin(5));assertFalse(check.complete(3,"missing",true));assertFalse(check.complete(4,"missing",false));assertTrue(check.active());assertTrue(check.complete(4,"missing",true));assertFalse(check.complete(4,"clear_window",true));assertFalse(check.begin(4));check.invalidate();assertEquals(PotCheckState.Result.UNKNOWN,check.result());}
    @Test public void localIssueRemainsAvailableThroughTheVisualSignal(){ControlState s=live();s.visualIssue="Heizung zuerst ausschalten";assertEquals(HomeVesselSignal.Kind.ACTION,HomeVesselSignal.from(s,1100).kind);assertEquals(s.visualIssue,HomeVesselSignal.from(s,1100).description());}
    @Test public void scaleHidesTheReadingWhenMissingIsConfirmed(){ControlState s=live();s.potCheck.begin(1);s.potCheck.complete(1,"missing",true);HomeScaleState scale=new HomeScaleState();for(int i=0;i<30;i++){s.weightRaw=20;s.samples++;s.statusAt=s.infoAt=1000+50*i;scale.observe(s,s.statusAt);}assertNull(scale.grams());assertEquals("— g",scale.text());}
}
